  "computer.introLinux": "每个机器人都有自己的 Linux 电脑——带浏览器、终端和自己文件的完整桌面，和其他机器人以及这台服务器都分开。电脑空闲时会休眠，需要时会唤醒；里面的东西不会丢。你可以随时观看或接管。",
