  "egress.accountIntro": "机器人电脑上的程序可以调用你的 API，而永远拿不到密钥：按机器人开启（机器人设置 → 阅读和密钥）。Sklubot 在电脑外部加上密钥，只用于保存时指定的主机，每个密钥第一次使用前都会问你。",
