  "egress.intro": "{name} 在它电脑上运行的脚本和工具可以通过 Sklubot 用你保存的秘密调用 API。密钥绝不进入电脑；只有每个秘密指定的主机可用；每个秘密的首次使用，以及读过外部内容后的改动，都会问你。",
