  "backup.guide.ovh.title": "在 OVHcloud 创建存储桶和密钥（用手机即可）",
  "backup.guide.ovh.1": "OVHcloud 控制面板 → Public Cloud → 你的项目 → Storage → Object Storage。",
  "backup.guide.ovh.2": "“Users”标签页：创建一个 Object Storage 用户。记下访问密钥和秘密密钥（… 按钮 → “View the secret key”）。",
  "backup.guide.ovh.3": "“Containers”标签页 → “Create an object container”：类型选“S3-compatible API”，填一个小写名称（例如 sklubot-backups），选一个区域（例如 Gravelines = gra），关联用户，然后点“Create”。",
  "backup.guide.ovh.4": "在这里：选择相同的区域，填写存储桶名称、访问密钥和秘密密钥，然后点“测试连接”。",
  "backup.guide.hetzner.title": "在 Hetzner 创建存储桶和密钥（用手机即可）",
  "backup.guide.hetzner.1": "Hetzner Console → 你的项目 → Object Storage → “Create Bucket”：选一个位置（例如 Falkenstein = fsn1），填一个唯一名称，可见性选“private”，然后点“Create & Buy now”。",
  "backup.guide.hetzner.2": "“Security”菜单 → “S3 Credentials”标签页 → “Generate credentials”，填写描述（例如 Sklubot）。",
  "backup.guide.hetzner.3": "立即复制访问密钥（上方）和秘密密钥（下方）：秘密密钥不会再显示。",
  "backup.guide.hetzner.4": "在这里：选择相同的位置，填写存储桶名称和两把密钥，然后点“测试连接”。",
  "backup.guide.scaleway.title": "在 Scaleway 创建存储桶和密钥（用手机即可）",
  "backup.guide.scaleway.1": "Scaleway 控制台 → Object Storage → “+ Create bucket”：选一个区域（例如 Paris = fr-par），填名称，可见性选“Private”，然后点“Create bucket”。",
  "backup.guide.scaleway.2": "账户菜单（右上角）→ “IAM & API keys” → “API keys”标签页 → “+ Generate API key”。",
  "backup.guide.scaleway.3": "对于 Object Storage，把存储桶所在项目选为首选项目，然后点“Generate API key”。复制访问密钥和秘密密钥（只显示一次）。",
  "backup.guide.scaleway.4": "在这里：选择相同的区域，填写存储桶名称和两把密钥，然后点“测试连接”。",
