  "lp.role.research": "调研和监测",
  "lp.what.kicker": "它们能做什么",
  "lp.what.title": "不是又一个聊天机器人。而是有真正工作的队友。",
  "lp.what.sub": "Sklubot 机器人不只是回答问题：它有工具、会跟进，并且真的把工作做完。",
  "lp.f.job.t": "一份工作",
  "lp.f.job": "角色、指令、技能。用几行字写下它的工作，或者从现成的模板开始。",
  "lp.f.memory.t": "一份记忆",
  "lp.f.memory": "它会记住你教它的东西：你的客户、你的偏好、你的写作方式。你想看就看，想删就删。",
  "lp.f.memory.n1": "喜欢简短的邮件",
  "lp.f.memory.n2": "重要客户：Moreau 工坊",
  "lp.f.memory.n3": "每周一 9 点开团队会",
  "lp.f.voice.t": "自己的声音",
  "lp.f.voice": "给你的机器人打电话，像打电话一样和它聊。它会用你为它挑选的声音出声回答。",
  "lp.f.pc.t": "自己的电脑",
  "lp.f.pc": "一台带浏览器的隔离 Linux 电脑，用来搜索、填表和准备文件。你可以实时看它的屏幕。",
  "lp.f.pc.pool": "免费套餐中，电脑按任务借用，用完即清除。",
  "lp.f.pc.task": "比较三份运费报价",
  "lp.f.ok.t": "任何不可撤销的事都先征得你同意",
  "lp.f.ok": "发送、付款、删除、发布：机器人会停下来，给你看它要做什么，然后等待。你可以允许一次，或者拒绝。",
  "lp.more": "还有",
  "lp.more.routines": "计划的例行任务",
  "lp.more.goals": "跟进的目标",
  "lp.more.group": "机器人之间的群聊",
  "lp.more.apps": "已连接的应用",
  "lp.more.pause": "随时暂停",
  "lp.video.captions": "法语",
  "lp.video.fallback": "你的浏览器无法播放这个视频：在这里下载。",
  "lp.video.filmLabel": "Sklubot 介绍短片，45 秒，带字幕",
  "lp.video.usageLabel": "一分钟 Sklubot 演示：创建账号、选择模板、和机器人对话、始终由你掌控",
  "lp.film.kicker": "短片",
  "lp.film.title": "45 秒了解 Sklubot。",
  "lp.film.sub": "你的团队、它的工作，以及始终掌控一切的你。可以开声音，也可以看字幕（法语）。",
  "lp.usage.kicker": "如何运作",
  "lp.usage.title": "1 分钟安装并上手。",
  "lp.usage.sub": "在应用里拍摄（法语）：创建账号、选择团队模板、给机器人写信、回答审批请求、打开“今天”、给机器人打电话。",
  "lp.usage.note": "以演示模式录制：机器人的回答是模拟的。",
  "lp.how.s1t": "创建你的账号",
  "lp.how.s1": "只需要一个邮箱地址和一个密码。",
  "lp.how.s1v": "只需要一个邮箱地址和一个密码。点一下就能确认你的地址。",
  "lp.how.s2t": "选择你的团队",
  "lp.how.s2": "从现成的模板或单个助理开始，给它起个名字。",
  "lp.how.s3t": "交给它第一项任务",
  "lp.how.s3": "像给同事写信那样写，或者直接打电话。机器人会开始工作，随时向你汇报，需要你时会问你。",
  "lp.tpl.kicker": "模板",
  "lp.tpl.title": "随时可以开工的团队。",
  "lp.tpl.sub": "每个模板创建的都是谨慎的机器人：它们的技能作为草稿，例行任务处于暂停，直到你批准。",
  "lp.tpl.bots_other": "{n} 个机器人",
  "lp.apps.kicker": "应用",
  "lp.apps.title": "在浏览器里，在电脑上，在你的口袋里。",
  "lp.apps.sub": "一个账号走遍各处：你的机器人和对话在每台设备上都跟着你。",
  "lp.apps.web.t": "在线版",
  "lp.apps.web": "无需安装。在电脑、平板或手机上打开 Sklubot 即可。",
  "lp.apps.web.meta": "无需安装",
  "lp.apps.windows.t": "Windows",
  "lp.apps.windows": "真正的窗口、通知，以及内置的 Relais，让你的机器人在你同意后操作你的电脑。",
  "lp.apps.linux.t": "Linux",
  "lp.apps.linux": "适用于 Ubuntu 和 Debian 的 .deb 安装包，其他系统用 AppImage。",
  "lp.apps.android.t": "Android",
  "lp.apps.android": "手机应用。首次启动时，输入这台服务器的地址。",
