  "lp.price.chooseFree": "免费开始",
  "lp.price.all": "价格详情",
  "lp.trust.kicker": "信任",
  "lp.trust.title": "专为让你放心交付真正的工作而打造。",
  "lp.trust.t1t": "账号相互隔离",
  "lp.trust.t1": "每个账号只能看到自己的机器人、文件和对话。机器人的电脑是彼此隔离的容器，位于互相看不见的网络中。",
  "lp.trust.t2t": "加密的秘密",
  "lp.trust.t2": "应用连接和已保存的密码在服务器上加密（AES-256-GCM）。",
  "lp.trust.t3t": "自由软件，可托管在欧洲",
  "lp.trust.t3": "Sklubot 以 MIT 许可证发布，运行在你选择的服务器上，可以在法国或欧洲其他地方。",
  "lp.trust.t4t": "始终由你掌控",
  "lp.trust.t4": "每个操作都有日志，有暂停按钮、花费上限，任何无法撤销的事都先征得你同意。",
  "lp.faq.kicker": "常见问题",
  "lp.faq.title": "大家常问的问题。",
  "lp.faq.q1": "Sklubot 上的机器人是什么？",
  "lp.faq.a1": "一个有角色、记忆、工具的 AI 助理，根据套餐还会有一台电脑。你像和同事一样和它对话；它也可以自己工作，按计划运行例行任务或朝着目标推进。",
  "lp.faq.q2": "机器人会捅娄子吗？",
  "lp.faq.a2": "新机器人是谨慎的：行动前会询问。任何无法撤销的事（发送、付款、删除、发布），它都会停下来等你同意，没有“始终允许”。你随时可以暂停它。",
  "lp.faq.q3": "我真的能和机器人说话吗？",
  "lp.faq.a3": "能：在对话里给机器人打电话，出声和它聊。它会用你为它挑选的声音回答。你也可以随时给它写信。",
  "lp.faq.q4": "需要安装什么吗？",
  "lp.faq.a4": "不需要：一切都能在浏览器里用，电脑和手机都行。如果你喜欢，也有 Windows 和 Linux 版应用，以及 Android 版应用。",
  "lp.faq.q5": "安装应用时 Windows 弹出警告，正常吗？",
  "lp.faq.a5": "正常。应用还没有签名，所以第一次运行时 Windows SmartScreen 会显示警告。点击“更多信息”，再点击“仍要运行”。你也可以在线使用 Sklubot，无需安装。",
  "lp.faq.q6": "使用哪些 AI 模型？",
  "lp.faq.a6": "这个服务提供的 AI 模型，或者如果你喜欢，也可以用你自己的 API 密钥。每个机器人都可以有自己的模型和备用模型。",
  "lp.faq.q7": "我的数据在哪里？",
  "lp.faq.a7": "在这个服务的服务器上。你可以随时在设置里导出数据或删除账号。",
  "lp.faq.q8": "为什么要确认邮箱地址？",
  "lp.faq.a8": "为了确认真的是你，也为了在你忘记密码时帮你。你可以马上四处看看；确认之后机器人就开始工作。",
  "lp.final.title": "你的团队在等你。",
  "lp.final.sub": "创建账号，选择模板，交给它第一项任务。",
